}{{if:r1=2|< }}{{if:r1=3|\\leqslant}}{{a}}$ {{if:k=1|ou|et}} $x{{if:r2=0|>}}{{if:r2=1|\\geqslant}}{{if:r2=2|< }}{{if:r2=3|\\leqslant}}{{b}}$ » ?","variables":[{"name":"a","expression":"-9..9"},{"name":"d","expression":"1..8"},{"name":"b","expression":"{{eval:a+d}}"},{"name":"k","expression":"0..1"},{"name":"s1","expression":"0..1"},{"name":"s2","expression":"0..1"},{"name":"r1","expression":"{{eval:s1+2*k}}"},{"name":"r2","expression":"{{eval:s2+2-2*k}}"}],"correction":{"steps":["La négation de « $A$ et $B$ » est « non $A$ ou non $B$ » ; la négation de « $A$ ou $B$ » est « non $A$ et non $B$ » : on nie chaque morceau **et** on change le connecteur.","La négation de « $>$ » est « $\\leqslant$ », celle de « $\\geqslant$ » est « $<$ » (et inversement) : une seule des deux relations est vraie pour chaque réel.","La négation de « $x{{if:r1=0|>}}{{if:r1=1|\\geqslant}}{{if:r1=2|< }}{{if:r1=3|\\leqslant}}{{a}}$ » est « $x{{if:r1=0|\\leqslant}}{{if:r1=1|< }}{{if:r1=2|\\geqslant}}{{if:r1=3|>}}{{a}}$ » et celle de « $x{{if:r2=0|>}}{{if:r2=1|\\geqslant}}{{if:r2=2|< }}{{if:r2=3|\\leqslant}}{{b}}$ » est « $x{{if:r2=0|\\leqslant}}{{if:r2=1|< }}{{if:r2=2|\\geqslant}}{{if:r2=3|>}}{{b}}$ ».","La négation est donc : « $x{{if:r1=0|\\leqslant}}{{if:r1=1|< }}{{if:r1=2|\\geqslant}}{{if:r1=3|>}}{{a}}$ {{if:k=1|et|ou}} $x{{if:r2=0|\\leqslant}}{{if:r2=1|< }}{{if:r2=2|\\geqslant}}{{if:r2=3|>}}{{b}}$ »."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"Il existe un réel $x$ tel que $x>{{a}}$ et $x^2\\leqslant{{c}}$."},{"content":"Il existe un réel $x$ tel que, si $x>{{a}}$, alors $x^2\\leqslant{{c}}$."},{"content":"Pour tout réel $x$, si $x>{{a}}$, alors $x^2\\leqslant{{c}}$."},{"content":"Il existe un réel $x$ tel que $x\\leqslant{{a}}$ et $x^2\\leqslant{{c}}$."}],"statement":"Quelle est la négation de la proposition « pour tout réel $x$, si $x>{{a}}$, alors $x^2>{{c}}$ » ?","variables":[{"name":"a","expression":"-6..6"},{"name":"c","expression":"0..40"}],"correction":{"steps":["La proposition affirme que **tout** réel $x$ qui vérifie $x>{{a}}$ vérifie aussi $x^2>{{c}}$.","Elle est fausse s'il existe **au moins un** réel $x$ qui vérifie l'hypothèse $x>{{a}}$ **sans** vérifier la conclusion, c'est-à-dire avec $x^2\\leqslant{{c}}$.","La négation est donc : « il existe un réel $x$ tel que $x>{{a}}$ et $x^2\\leqslant{{c}}$ ». La négation de « si $P$, alors $Q$ » est « $P$ et non $Q$ » : ce n'est pas une implication."]},"correctChoiceIndex":["0"]}],"shared":{"cleanCoefficients":true},"test_specs":[{"expected":{"status":"correct"},"variables":{"b":"2","c":"3","r":"0"},"description":"pour tout > : bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"b":"2","c":"3","r":"0"},"description":"pour tout > : autre choix refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"b":"-1","c":"-4","r":"3"},"description":"pour tout ≤ : bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"b":"-1","c":"-4","r":"3"},"description":"pour tout ≤ : autre choix refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"c":"5","m":"2","p":"1","r":"1"},"description":"il existe ≥ : bonne réponse","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"c":"5","m":"2","p":"1","r":"1"},"description":"il existe ≥ : autre choix refusé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"1","d":"3","k":"0","s1":"0","s2":"1"},"description":"et : bonne réponse","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"1","d":"3","k":"0","s1":"0","s2":"1"},"description":"et : autre choix refusé","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"1","d":"3","k":"1","s1":"0","s2":"1"},"description":"ou : bonne réponse","variationIndex":2,"selectedChoices":[