insert into _plab_modeles values ('0ab3faa5-a660-4841-9a5f-6563458d2489', $plab$Logique$plab$, $plab$Quantificateurs et négation$plab$, $plab$négation d'une proposition$plab$, array['1_SPE'], '1_SPE', '1SPE-204',
  $plab${"title":"Nier une proposition","description":"Choisir la négation d'une proposition quantifiée (« pour tout », « il existe ») ou d'une proposition avec « et », « ou »","variations":[{"choices":[{"content":"Il existe un réel $x$ tel que $x^2{{b;+}}x{{if:r=0|\\leqslant}}{{if:r=1|< }}{{if:r=2|\\geqslant}}{{if:r=3|>}}{{c}}$."},{"content":"Pour tout réel $x$, $x^2{{b;+}}x{{if:r=0|\\leqslant}}{{if:r=1|< }}{{if:r=2|\\geqslant}}{{if:r=3|>}}{{c}}$."},{"content":"Il existe un réel $x$ tel que $x^2{{b;+}}x{{if:r=0|>}}{{if:r=1|\\geqslant}}{{if:r=2|< }}{{if:r=3|\\leqslant}}{{c}}$."},{"content":"Il existe un réel $x$ tel que $x^2{{b;+}}x{{if:r=0|< }}{{if:r=1|\\leqslant}}{{if:r=2|>}}{{if:r=3|\\geqslant}}{{c}}$."}],"statement":"Quelle est la négation de la proposition « pour tout réel $x$, $x^2{{b;+}}x{{if:r=0|>}}{{if:r=1|\\geqslant}}{{if:r=2|< }}{{if:r=3|\\leqslant}}{{c}}$ » ?","variables":[{"name":"b","expression":"-5..5"},{"name":"c","expression":"-9..9"},{"name":"r","expression":"0..3"}],"conditions":[],"correction":{"steps":["Pour nier une proposition quantifiée, on **change le quantificateur** (« pour tout » devient « il existe », et inversement) **et** on **nie la propriété**.","« Pour tout réel $x$ » devient « il existe un réel $x$ tel que ».","La négation de « $>$ » est « $\\leqslant$ », celle de « $\\geqslant$ » est « $<$ » (et inversement) : une seule des deux relations est vraie pour chaque réel.","La négation est donc : « il existe un réel $x$ tel que $x^2{{b;+}}x{{if:r=0|\\leqslant}}{{if:r=1|< }}{{if:r=2|\\geqslant}}{{if:r=3|>}}{{c}}$ »."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"Pour tout réel $x$, ${{m}}x{{p;+}}{{if:r=0|\\leqslant}}{{if:r=1|< }}{{if:r=2|\\geqslant}}{{if:r=3|>}}{{c}}$."},{"content":"Il existe un réel $x$ tel que ${{m}}x{{p;+}}{{if:r=0|\\leqslant}}{{if:r=1|< }}{{if:r=2|\\geqslant}}{{if:r=3|>}}{{c}}$."},{"content":"Pour tout réel $x$, ${{m}}x{{p;+}}{{if:r=0|>}}{{if:r=1|\\geqslant}}{{if:r=2|< }}{{if:r=3|\\leqslant}}{{c}}$."},{"conte