 : 100","variationIndex":0},{"answers":["20"],"expected":{"status":"correct"},"variables":{"n":"6"},"description":"v1 : n = 6 → 20","variationIndex":1},{"answers":["120"],"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v1 : 120 (triplets ordonnés)","variationIndex":1}],"options":{"constraints":{"spaces":"off"}}}$plab$::jsonb);
