-- Tags que les modèles portent déjà (relevé) : exigés à l'identique, laissés en place.
drop table if exists pg_temp._plab_tags_avant;
create temporary table _plab_tags_avant (
	id uuid not null references _plab_modeles (id),
	tag_grade text not null, tag_code text not null
);
insert into _plab_tags_avant values
